INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62336747', 62336747, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'SEWA JARINGAN UTAMA KONEKSI INTERNET KEMENTERIAN PPN/BAPPENAS TAHUN 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota) | DKI Jakarta, Jakarta Pusat (Kota) | DKI Jakarta, Jakarta Pusat (Kota) | Kepulauan Riau, Batam (Kota) | DKI Jakarta, Jakarta Selatan (Kota)', 3781454760, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Penyediaan Layanan Bandwidth Internet Kementerian PPN/Bappenas, Gd. Menara Bappenas (MB), Gd. Taman Suropati, Gd. Proklamasi, BP. Batam dan Wisma Kodel', 'Lingkup Kegiatan a. Penyediaan Layanan Bandwidth Internet Kementerian PPN/Bappenas, Gd. Menara Bappenas (MB): 1) Menyediakan layanan akses internet IP Transit Internasional Gold dengan bandwidth 1 Gbps di lokasi Jalan H.R. Rasuna Said, Kuningan, Setiabudi, Jakarta Selatan. 2) Melakukan perpanjangan AS Number dan IP Publik. 3) Termasuk penyediaan router dan switch yang sesuai dengan bandwidth yang disediakan, serta penyediaan perangkat monitoring. 4) Melakukan alih pengetahuan kepada Kementerian PPN/Bappenas terkait peningkatan kemampuan dasar teknologi dan informasi. 5) Media Akses yang digunakan adalah Fiber Optic end to end. 6) SLA yang dijaminkan yaitu 99%. b. Penyediaan Layanan Bandwidth Internet Kementerian PPN/Bappenas Gd. Taman Suropati No.2 (TS): 1) Menyediakan layanan akses Internet Dedicated Internasional Gold dengan bandwidth 1 Gbps di lokasi Jalan Taman Suropati No. 2, Jakarta 10310. 2) Media Akses yang digunakan adalah Fiber Optic end to end. 3) SLA yang dijaminkan yaitu 99%. 6 c. Penyediaan Layanan Bandwidth Internet Gedung Proklamasi (Pusbindiklatren, Bappenas) 1) Menyediakan layanan akses Internet Dedicated Internasional Gold dengan bandwidth 150 Mbps Internasional di lokasi Gedung Proklamasi, Jalan Proklamasi No. 70, Menteng, Jakarta Pusat. 2) Media Akses yang digunakan adalah Fiber Optic end to end. SLA yang dijaminkan yaitu 99%. d. Penyediaan Layanan Bandwidth Internet DC BP Batam: 1) Menyediakan layanan akses Internet Dedicated Internasional Gold area Sumatera dengan bandwidth 50 Mbps Internasional di lokasi DC BP Batam. 2) Media Akses yang digunakan adalah Fiber Optic end to end. 3) SLA yang dijaminkan yaitu 99%. e. Penyediaan Layanan Bandwidth Internet Gedung Wisma Kodel 1) Penyediaan Layanan Bandwidth Internet Gedung Wisma Kodel layanan akses Internet Dedicated Internasional Gold dengan bandwidth 200 Mbps Internasional di lokasi Wisma Kodel Jalan H.R Rasuna Said, Kuningan , Jakarta Selatan. 2) Media Akses yang digunakan adalah Fiber Optic end to end. 3) SLA yang dijaminkan yaitu 99%.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 3, 431060);
