INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62986979', 62986979, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Belanja Jilid Buku Softcover', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Sidoarjo (Kab.)', 11655000, 'January 2026', 'APBD', 1, 1, '350 Buku', 'Jilid Buku Softcover ini meliputi kegiatan penjilidan dokumen (DHKP) dengan menggunakan sampul lunak (softcover) guna menunjang kebutuhan administrasi, pelaporan, dokumentasi, dan arsip pada perangkat daerah. Pekerjaan ini bertujuan untuk menghasilkan dokume DHKP yang rapi, kuat, mudah digunakan, serta memiliki tampilan yang profesional', 'Jilid Buku Softcover 1. Nama Pekerjaan Jilid Buku Softcover 2. Jenis Pekerjaan Jasa Percetakan / Penjilidan Dokumen 3. Ukuran Penjilidan F4 (21,5 x 33 cm) 4. Jumlah Halaman Menyesuaikan dengan dokumen yang dijilid Ketebalan buku disesuaikan dengan kapasitas jilid softcover 5. Sampul (Cover) Jenis: Softcover Bahan: Art Carton / Ivory / Kertas Karton tebal setara Gramatur: 210 – 260 gsm Finishing sampul: Laminasi doff atau glossy Warna: Full color atau satu warna sesuai kebutuhan 6. Isi Buku Kertas isi disediakan oleh pemberi pekerjaan atau penyedia (sesuai kesepakatan) Susunan halaman rapi, tidak terbalik, dan tidak terlipat 7. Metode Penjilidan Lem panas (perfect binding) atau metode lain yang setara Daya rekat kuat, tidak mudah lepas Punggung buku rapi dan rata 8. Kualitas Pengerjaan Jilidan kuat dan presisi Sudut buku rapi dan tidak tajam Tidak terdapat noda lem, sobekan, atau kerusakan halaman Buku dapat dibuka dengan baik tanpa merusak jilidan 9. Toleransi Pekerjaan Toleransi kesalahan maksimal ±1% dari total jumlah buku 10. Pengemasan Dikemas rapi dan aman Terlindung dari debu, air, dan benturan selama pengiriman 11. Kondisi Hasil Pekerjaan Baru, belum pernah digunakan Bebas cacat produksi dan cacat penjilidan 12. Waktu Penyelesaian Sesuai jadwal yang ditetapkan dalam kontrak atau surat pesanan 13. Tempat Penyerahan Lokasi yang ditentukan oleh PPK/Pejabat Pengadaan 14. Pemeriksaan dan Serah Terima Dilakukan oleh PPK Dibuktikan dengan Berita Acara Serah Terima (BAST)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 436873);
