INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62987965', 62987965, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Belanja Kertas HVS - Penetapan', 'Barang', 'E-Purchasing', 'Jawa Timur, Sidoarjo (Kab.)', 122175000, 'October 2026', 'APBD', 1, 1, '1810 Rim', 'Uraian pekerjaan Belanja Kertas HVS Ukuran F4 ini meliputi kegiatan pengadaan, penyediaan, dan penyerahan kertas HVS ukuran F4 untuk mendukung kelancaran kegiatan administrasi perkantoran, pelayanan publik, serta pencetakan dan penggandaan dokumen resmi pada perangkat daerah. Pekerjaan ini mencakup penyediaan kertas HVS ukuran F4 yang memenuhi spesifikasi teknis, dengan kualitas baik, permukaan halus, warna putih cerah, dan kompatibel digunakan pada mesin fotokopi, printer inkjet, maupun printer laser. Kertas yang disediakan harus dalam kondisi baru, tidak rusak, tidak lembab, serta dikemas rapi dalam kemasan pabrik', 'Spesifikasi Teknis Belanja Kertas HVS Ukuran F4 1. Nama Barang Kertas HVS Ukuran F4 2. Jenis Barang Alat Tulis Kantor (ATK) 3. Ukuran Ukuran kertas: F4 Dimensi: ± 21,5 cm x 33 cm 4. Bahan Bahan dasar: Pulp kayu berkualitas Bebas dari bahan berbahaya dan aman digunakan untuk keperluan administrasi perkantoran 5. Gramatur 70 gsm 6. Warna Putih cerah 7. Tingkat Keputihan (Brightness) Minimal 90% 8. Karakteristik Teknis Permukaan halus dan rata Tidak mudah tembus tinta Tidak mudah macet pada mesin Tidak mudah robek Cocok untuk penggunaan mesin fotokopi, printer inkjet, dan printer laser 9. Kemasan Dikemas dalam rim (500 lembar) Kemasan pabrik masih tersegel, rapi, dan tidak rusak Setiap kemasan dilengkapi identitas produk 10. Kondisi Barang Baru (bukan rekondisi) Tidak lembab, tidak cacat, dan tidak menguning 11. Standar Mutu Memenuhi standar mutu kertas HVS yang berlaku di Indonesia Disarankan memiliki sertifikasi ramah lingkungan (apabila tersedia) 12. Jumlah Sesuai dengan kebutuhan dan tercantum dalam kontrak atau surat pesanan 13. Tempat Pengiriman Sesuai lokasi yang ditetapkan oleh PPK/Pejabat Pengadaan 14. Jangka Waktu Pengiriman Maksimal sesuai ketentuan dalam kontrak/SP 15. Pemeriksaan dan Serah Terima Barang diperiksa oleh PPK Serah terima dituangkan dalam Berita Acara Serah Terima (BAST)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 437248);
