INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62295423', 62295423, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Biaya Perlengkapan Jamuan Dalam Kegiatan Operasional dan Pemeliharaan Kantor Pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 30000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1.0 Tahun', 'Pekerjaan ini mencakup pemenuhan kebutuhan perlengkapan jamuan untuk mendukung pelaksanaan kegiatan penerimaan tamu dan pertemuan yang dilaksanakan di lingkungan Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan selama jangka waktu 1 tahun. Perlengkapan jamuan disediakan secara bertahap sesuai dengan kebutuhan kegiatan yang dilaksanakan sepanjang tahun untuk menunjang kelancaran pelaksanaan jamuan.', 'Perlengkapan jamuan yang disediakan merupakan perlengkapan penunjang penyajian jamuan yang layak dan sesuai kebutuhan kegiatan. Perlengkapan meliputi antara lain peralatan dan wadah penyajian, perlengkapan makan dan minum, perlengkapan sekali pakai, serta perlengkapan pendukung lainnya yang diperlukan dalam pelaksanaan jamuan. Penyediaan perlengkapan jamuan dilaksanakan selama 1 tahun dan disesuaikan dengan jumlah serta karakter kegiatan yang dilaksanakan. Seluruh perlengkapan disediakan dalam kondisi bersih, layak pakai, dan siap digunakan sesuai ketentuan administrasi yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 437843);
